      pt: "Morskie Oko é o maior e mais conhecido lago das montanhas Tatra. Situa-se a uma altitude de 1.395 metros e está rodeado por picos de granito que se elevam quase 1.000 metros.",
      fr: "Morskie Oko est le lac le plus grand et le plus célèbre des Tatras. Situé à 1 395 mètres d'altitude, il est entouré de sommets granitiques s'élevant à 1 000 mètres au-dessus de lui.",
