      es: ["El lago está rodeado por un impresionante acantilado de granito de más de 1.000 metros de altura.", "Recibió su nombre (Ojo del Mar) por la creencia de que está conectado con el mar bajo tierra.", "Su superficie es de aproximadamente 35 hectáreas y su cuenca fue excavada por glaciares de la edad de hielo.", "Se encuentra a una altitud de 1.395 metros sobre el nivel del mar, en el corazón del Parque Nacional Tatra.", "Su profundidad máxima alcanza los 51 metros, lo que lo sitúa entre los lagos más profundos de la región.", "El lago se congela completamente en invierno durante un promedio de cinco a seis meses y está cubierto por una espesa capa de nieve."],
      pt: ["O lago é cercado por uma impressionante escarpa de granito com mais de 1000 metros de altura.", "Recebeu o nome (Olho do Mar) devido à crença de que está ligado ao mar por via subterrânea.", "A sua área é de cerca de 35 hectares e o seu leito foi escavado por glaciares da era glacial.", "Situa-se a 1395 metros acima do nível do mar, no coração do Parque Nacional Tatra.", "A sua profundidade máxima atinge os 51 metros, o que o coloca entre os lagos mais profundos da região.", "No inverno, o lago gela completamente durante cinco a seis meses, em média, e fica coberto por uma espessa camada de neve."],
      fr: ["Le lac est entouré de falaises granitiques impressionnantes de plus de 1 000 mètres de haut.", "Il tire son nom (Œil de la Mer) d'une légende affirmant qu'il est relié à la mer par des galeries souterraines.", "Sa superficie est d'environ 35 hectares et sa cuvette a été creusée par des glaciers.", "Il est situé à 1 395 mètres d'altitude, au cœur du parc national des Tatras.", "Sa profondeur maximale atteint 51 mètres, ce qui en fait l'un des lacs les plus profonds de la région.", "En hiver, le lac gèle complètement pendant environ cinq à six mois et se couvre d'une épaisse couche de neige."],
