      ro: ["Înălțime de 1.603 metri", "Vârf de graniță între Polonia și Cehia", "Capelă barocă Sf. Laurențiu din 1681", "Climat extrem de vântos pe vârf"],
      en: ["Elevation of 1,603 meters", "Border peak between Poland and Czechia", "Baroque St. Lawrence Chapel from 1681", "Extremely windy climate at the summit"],
