    name: { de: "Biebrza-Sümpfe", hu: "Biebrza-mocsarak", ro: "Mlaștinile Biebrza", en: "Biebrza Marshes"},
    image: "/poi-images/poland-biebrza-marshes-nature-v2.webp",
