      ro: ["Cel mai înalt baraj din Polonia (82 m)", "Linie de țărm de peste 150 km", "Adâncime maximă de cca. 60 m", "Are o telecabină modernă"],
      en: ["Features Poland's highest dam (82 m)", "Shoreline extends over 150 km", "Maximum depth of about 60 meters", "Served by a scenic cable car"],
      es: ["Presa más alta de Polonia (82 m)", "Línea de costa de más de 150 km", "Profundidad máxima de unos 60 m", "Cuenta con un moderno teleférico"],
