    type: "valley",
    name: { de: "Tal der Fünf Polnischen Seen", hu: "Öt-lengyel-tó völgye", ro: "Valea celor Cinci Lacuri Poloneze", en: "Five Polish Lakes Valley"},
    image: "/poi-images/poland-five-lakes-valley-nature-v2.webp",
