    type: "landmark",
    name: { de: "Steilküste von Wolin", hu: "Wolini sziklák", ro: "Faleza Wolin", en: "Wolin Cliffs"},
    image: "/poi-images/poland-wolin-cliffs-nature-v2.webp",
