      hu: ["Maximális mélysége 83 méter", "Lengyelország második legnagyobb belvízi szigete", "Területe kb. 18,7 km²", "Nagyon tiszta víz (I. osztályú)"],
      ro: ["Adâncime maximă de 83 de metri", "A doua cea mai mare insulă interioară", "Suprafață de aproximativ 18,7 km²", "Apă foarte curată (clasa I)"],
